args.source:
import type { Plugin } from "../../kernel/types";

const plugin: Plugin = {
  id: "local-provider",
  name: "Local Provider",
  version: "1.0.0",
  async onLoad(ctx) {
    ctx.register({
      kind: "provider",
      provider: {
        id: "local-response",
        label: "Local",
        defaultModel: "local",
        async *chat(_req: any, _tctx: any): AsyncGenerator<any> {
          yield { type: "delta", delta: { text: "LOCAL-OK" } };
          yield { type: "usage", usage: { input: 1, output: 1 } };
          yield { type: "done" };
        },
      },
    });
  },
};

export default plugin;

